      "attack_scenario": "An authenticated attacker invokes the exported `'use server'` action `getMonthlyAttendance` via a direct HTTP POST with a victim's Supabase UUID as `userId`; the admin client returns the victim's full monthly attendance records (dates, in/out status) without any authorization failure.",
      "checklist_id": "PROP-e5782b58-pre-008"
    },
    "text": "Non-admin users must only access their own attendance records; IDOR on user_id must be prevented.",
    "assertion": "forall query(user, target_user_id): user.is_admin == false => target_user_id == user.id",
    "covers": "SG-007",
    "severity": "HIGH",
    "type": "pre-condition"
  }
}

